# Smoke test for R/helpers.R using native R:  Rscript tests/helpers_test.R
suppressPackageStartupMessages({ library(ggplot2); library(dplyr); library(tidyr) })
source("R/helpers.R")
ok <- function(label, expr) {
  r <- tryCatch({ force(expr); "ok" }, error = function(e) paste("ERROR:", conditionMessage(e)))
  cat(sprintf("%-38s %s\n", label, r))
}
d <- PlantGrowth
ok("t test", { r <- ag_result_two_group(t.test(weight ~ group, data = droplevels(subset(d, group != "trt2"))), droplevels(subset(d, group != "trt2")), "weight", "group", c("ctrl","trt1"), "Welch's t test"); print(r) })
ok("one-way + tukey", { fit <- aov(weight ~ group, d); mc <- emmeans::contrast(emmeans::emmeans(fit, ~group), "pairwise", adjust = "tukey"); r1 <<- ag_result_anova(fit, mc, d, "weight", "group", "One-way ANOVA", "Tukey"); print(r1) })
ok("dunnett", { fit <- aov(weight ~ group, d); mc <- emmeans::contrast(emmeans::emmeans(fit, ~group), "trt.vs.ctrl", ref = "ctrl"); print(ag_emm_comparisons(mc)) })
ok("welch + games-howell", { t <- oneway.test(weight ~ group, d); print(ag_result_htest_groups(t, ag_games_howell(d$weight, d$group), d, "weight", "group", "Welch's ANOVA", "Games-Howell")) })
ok("kruskal + dunn", { t <- kruskal.test(weight ~ group, d); print(ag_result_htest_groups(t, ag_dunn(d$weight, d$group), d, "weight", "group", "Kruskal-Wallis", "Dunn")) })
tg <- ToothGrowth; tg$dose <- factor(tg$dose)
ok("two-way III + simple effects", { fit <- lm(len ~ supp * dose, data = tg, contrasts = list(supp = contr.sum, dose = contr.sum)); mc <- emmeans::contrast(emmeans::emmeans(fit, ~ supp | dose), "pairwise", adjust = "sidak"); print(ag_result_anova2(fit, mc, tg, "len", c("supp","dose"), "III")) })
ok("two-way I", { fit <- lm(len ~ supp * dose, data = tg); print(ag_anova2_table(fit, "I")) })
cw <- ChickWeight; cw$Time <- factor(cw$Time); cw <- subset(cw, Time %in% c(0, 10, 21))
ok("mixed", { suppressPackageStartupMessages(library(lmerTest)); fit <- lmerTest::lmer(weight ~ Diet * Time + (1 | Chick), data = cw); mc <- emmeans::contrast(emmeans::emmeans(fit, ~ Diet | Time, lmer.df = "satterthwaite"), "trt.vs.ctrl"); print(ag_result_mixed(fit, mc, cw, "weight", NULL)) })
ok("correlation", print(ag_result_cor(cor.test(mtcars$wt, mtcars$mpg), mtcars, "wt", "mpg", "pearson")))
ok("lm", { r <- ag_result_lm(lm(mpg ~ wt, mtcars), mtcars, "wt", "mpg"); print(r); stopifnot(nrow(r$curve) == 200) })
ok("poly2", print(ag_result_lm(lm(mpg ~ poly(wt, 2, raw = TRUE), mtcars), mtcars, "wt", "mpg", "poly2")$summary))
ok("4pl", { dn <- subset(DNase, Run == 1); fit <- nls(density ~ SSfpl(log10(conc), bottom, top, logEC50, scal), data = dn); print(ag_result_nls(fit, dn, "conc", "density", "4pl")) })
ok("michaelis-menten", { pt <- subset(Puromycin, state == "treated"); fit <- nls(rate ~ SSmicmen(conc, Vmax, Km), pt); print(ag_result_nls(fit, pt, "conc", "rate", "mm")$summary) })
ok("descriptive", print(ag_descriptive(d, "weight", "group")))
ok("normality", print(ag_normality(d, "weight", "group")))
ok("result json", cat(substr(ag_result_json(r1), 1, 300), "\n"))
ok("describe", cat(ag_describe(tg), "\n"))
ok("preview", cat(substr(ag_preview(tg, 3), 1, 300), "\n"))
ok("eval_json warning", cat(ag_eval_json("x <- as.numeric('a'); 'hi'"), "\n"))
ok("eval_json error", cat(ag_eval_json("stop('boom')"), "\n"))
ok("eval_json error call", cat(ag_eval_json("log(-1:'a')"), "\n"))
p <- ggplot(d, aes(group, weight)) + geom_point(position = position_jitter(width = .15, height = 0, seed = 1)) +
  stat_summary(fun.data = ag_mean_sem, geom = "errorbar", width = .3) +
  ag_brackets(r1, d, "group", "weight") + ag_theme_lab()
ok("draw svg", { j <- jsonlite::fromJSON(ag_draw(p, tempfile(fileext = ".svg"), "svg", 4, 4, inline = TRUE)); stopifnot(j$ok); cat(nchar(j$svg), "chars, warnings:", length(j$warnings), "\n") })
for (fmt in c("pdf", "png", "tiff")) ok(paste("draw", fmt), { f <- tempfile(); j <- jsonlite::fromJSON(ag_draw(p, f, fmt, 4, 4)); stopifnot(j$ok); cat(file.size(f), "bytes\n") })
p2 <- ggplot(mtcars, aes(wt, mpg)) + geom_point() + ag_fit_curve(ag_result_lm(lm(mpg ~ wt, mtcars), mtcars, "wt", "mpg")) + ag_corner_label("r = 0.8")
ok("fit curve plot", { j <- jsonlite::fromJSON(ag_draw(p2, tempfile(), "svg", 4, 4)); stopifnot(j$ok) })
ok("rdata roundtrip", { plot_1 <<- p; data_1 <<- d; f <- tempfile(fileext = ".RData"); ag_save_rdata(f, c("data_1", "plot_1", "missing_obj"), '{"a":1}'); j <- jsonlite::fromJSON(ag_load_rdata(f), simplifyVector = FALSE); stopifnot(j$project == '{"a":1}', length(j$frames$data_1$rows) == 30); cat(paste(unlist(j$objects), collapse=","), "\n") })
ok("check code", cat(ag_check_code("log10(value"), ag_check_code("log10(value)"), "\n"))
